solution:
fn greet(name: Str) -> Str {
  return "Hello, " + name + "!";
}

fn create_email(user: Str, domain: Str) -> Str {
  return user + "@" + domain;
}

fn main() -> Int {
  let email = create_email("alice", "example.com");
  return email.len();
}
